import { forwardRef, type AnchorHTMLAttributes } from 'react';

type NavLinkSize = 'sm' | 'default' | 'lg';

export type NavLinkProps = {
  size?: NavLinkSize;
  active?: boolean;
  disabled?: boolean;
  children: string;
  href: string;
  className?: string;
} & Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export const NavLink = forwardRef<HTMLAnchorElement, NavLinkProps>(
  (
    {
      size = 'default',
      active = false,
      disabled = false,
      children,
      href,
      className,
      ...props
    },
    ref,
  ) => {
    const classes = cn(
      'nav-link',
      `nav-link--${size}`,
      active && 'nav-link--active',
      disabled && 'nav-link--disabled',
      className,
    );

    return (
      <a
        ref={ref}
        className={classes}
        href={href}
        aria-current={active ? 'page' : undefined}
        aria-disabled={disabled || undefined}
        {...props}
      >
        <span className="nav-link__text">{children}</span>
      </a>
    );
  },
);

NavLink.displayName = 'NavLink';

/* -------------------------------------------------------------------------
   Nav Link

   Internal navigation link. Child of Navbar.
   Neutral text, full contrast on hover/active. Underline on active.

   Sizes:    sm, default, lg
   States:   default, hover, active, disabled
   ------------------------------------------------------------------------- */

.nav-link {
  display: inline-flex;
  align-items: center;
  padding: 0;
  background: none;
  border: none;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--nav-link-fg-default);
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  /* ATOM --animation-ease (0.2s ease) para color; tracking de su nav-menu__label */
  letter-spacing: var(--letter-spacing-tight);
  transition: color var(--duration-200) ease;
  position: relative;
}

.nav-link:hover:not(.nav-link--disabled):not(.nav-link--active) {
  color: var(--nav-link-fg-hover);
}

.nav-link:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-radius: 0.125em;
}

@media (prefers-reduced-motion: reduce) {
  .nav-link {
    transition-duration: 0ms;
  }
  .nav-link__caret {
    transition-duration: 0ms;
  }
}

/* ---- Sizes ---- */

.nav-link--sm      { font-size: var(--font-size-xs); }
.nav-link--default { font-size: var(--font-size-sm); }
.nav-link--lg      { font-size: var(--font-size-base); }

/* ---- Active ---- */

.nav-link--active {
  color: var(--nav-link-fg-active);
  cursor: default;
}

.nav-link--active .nav-link__text::before {
  transform-origin: left;
  transform: scaleX(1) rotate(0.001deg);
}

/* ---- Disabled ---- */

.nav-link--disabled {
  color: var(--nav-link-fg-disabled);
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Parts ---- */

.nav-link__text {
  display: inline;
  position: relative;
}

/* ---- Dropdown variant ----
   Trigger de menu dentro de un navbar: caret que rota al abrir y el mismo
   subrayado del estado activo mientras el menu esta abierto. El estado lo
   lleva aria-expanded (accesibilidad = fuente de verdad del estilo). El panel
   es el componente dropdown-menu; aqui solo vive el trigger. */

.nav-link--dropdown {
  gap: 0.375em;
}

.nav-link__caret {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  transition: rotate var(--duration-300) var(--easing-out);
}

.nav-link__caret svg {
  width: 100%;
  height: 100%;
}

.nav-link--dropdown[aria-expanded='true'] {
  color: var(--nav-link-fg-active);
}

.nav-link--dropdown[aria-expanded='true'] .nav-link__caret {
  rotate: 180deg;
}

.nav-link--dropdown[aria-expanded='true'] .nav-link__text::before {
  transform-origin: left;
  transform: scaleX(1) rotate(0.001deg);
}

/* ---- Underline ---- */

/* Contrato citado de ATOM [data-underline-link]: offset -0.0625em, alto
   0.0625em, transform 0.6s con la cubica firma, origen right->left. */
.nav-link__text::before {
  content: "";
  position: absolute;
  bottom: -0.0625em;
  left: 0;
  width: 100%;
  height: 0.0625em;
  background-color: var(--nav-link-indicator-active);
  transition: transform var(--duration-600) var(--easing-osmo);
  transform-origin: right;
  transform: scaleX(0) rotate(0.001deg);
}

/* ---- Underline alt (ATOM [data-underline-link="alt"]) ----
   Para links que YA estan subrayados (footers, listas): al hover la linea sale
   por la derecha y una segunda reentra por la izquierda con 0.3s de delay. */

.nav-link--underline-alt .nav-link__text::before {
  transform-origin: left;
  transform: scaleX(1) rotate(0.001deg);
  transition-delay: var(--duration-300);
}

.nav-link--underline-alt .nav-link__text::after {
  content: "";
  position: absolute;
  bottom: -0.0625em;
  left: 0;
  width: 100%;
  height: 0.0625em;
  background-color: var(--nav-link-indicator-active);
  transition: transform var(--duration-600) var(--easing-osmo);
  transform-origin: right;
  transform: scaleX(0) rotate(0.001deg);
}

@media (hover: hover) and (pointer: fine) {
  .nav-link--underline-alt:hover:not(.nav-link--disabled) .nav-link__text::before {
    transform-origin: right;
    transform: scaleX(0) rotate(0.001deg);
    transition-delay: 0s;
  }
  .nav-link--underline-alt:hover:not(.nav-link--disabled) .nav-link__text::after {
    transform-origin: left;
    transform: scaleX(1) rotate(0.001deg);
    transition-delay: var(--duration-300);
  }
}

@media (hover: hover) and (pointer: fine) {
  .nav-link:hover:not(.nav-link--disabled):not(.nav-link--active) .nav-link__text::before,
  [data-hover]:hover .nav-link:not(.nav-link--disabled):not(.nav-link--active) .nav-link__text::before {
    transform-origin: left;
    transform: scaleX(1) rotate(0.001deg);
  }
}

/* -------------------------------------------------------------------------
   Nav Link — MOTION (subrayado)

   Separado de la pintura a proposito: es la parte que el panel de estilos de
   Webflow no puede declarar. Necesita un pseudo-elemento y un estado de
   ANCESTRO (`:hover > hijo`), y el panel no expresa ninguno de los dos. Por eso
   viaja en el canal `webflow.css`, igual que button-text-swap y
   whatsapp-button-motion. Color, tamano y tracking del link si se declaran alla
   como Variables nativas.

   El indicador se ancla al PROPIO __text (position: relative), no al link como
   en nav-link.css. Esa es la diferencia que hace consumible este subrayado
   desde un mega-nav: su boton lleva caret y padding propio, asi que anclarlo al
   link subrayaria tambien la flecha y obligaria al host a declarar `position`
   en el padre. Anclado al texto, el host no declara nada.

   EXIGE la anatomia: un contenedor cualquiera > .nav-link__text. Sin ese hijo
   no hay nada que subrayar — reimplementar el link con una clase de etiqueta
   propia es lo que dejaba el mega-nav sin animacion.
   ------------------------------------------------------------------------- */

.nav-link__text {
  position: relative;
}

/* Contrato citado de ATOM [data-underline-link]: offset -0.0625em, alto
   0.0625em, transform 0.6s con la cubica firma, origen right->left. */
.nav-link__text::before {
  content: "";
  position: absolute;
  bottom: -0.0625em;
  left: 0;
  width: 100%;
  height: 0.0625em;
  background-color: var(--nav-link-indicator-active);
  transition: transform var(--duration-600) var(--easing-osmo);
  transform-origin: right;
  transform: scaleX(0) rotate(0.001deg);
}

/* El hover vive en el ancestro para que el area sensible sea el control entero
   (boton + caret), no solo la caja del texto. */
:hover > .nav-link__text::before {
  transform-origin: left;
  transform: scaleX(1) rotate(0.001deg);
}

@media (prefers-reduced-motion: reduce) {
  .nav-link__text::before {
    transition-duration: 0ms;
  }
}

